test("corregirMovimiento: deja el stock como si el movimiento no se hubiera hecho, sin borrar nada (ADR-001)", () => {
  const movs = registrarMovimiento(conIngreso(), { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 3 });
  const corregida = corregirMovimiento(movs, 1);
  assert.equal(stock(corregida, "A1", "LPZ"), 10);
  assert.equal(corregida.length, 3);
  assert.equal(movs.length, 2);
  assert.ok(Object.isFrozen(corregida));
});

test("corregirMovimiento: índice inválido y RF-002", () => {
  assert.throws(() => corregirMovimiento(conIngreso(), 5), RangeError);
  assert.throws(() => corregirMovimiento(conIngreso(), -1), RangeError);
  const movs = registrarMovimiento(conIngreso(), { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 8 });
  assert.throws(() => corregirMovimiento(movs, 0), /Stock insuficiente/);
});
